import {createAIServices} from '../../services/ai.services';
import {createReceiptServices} from '../../services/receipt.service';
import {createTicketServices} from '../../services/ticket.service';
import {useFetchRequest} from '../useFetch';

export const useAIServices = () => {
  const fetchRequest = useFetchRequest();
  return createAIServices(fetchRequest);
};

export const useTicketServices = () => {
  const fetchRequest = useFetchRequest();
  return createTicketServices(fetchRequest);
};

export const useReceiptServices = () => {
  const fetchRequest = useFetchRequest();
  return createReceiptServices(fetchRequest);
};
