import {Icon} from '@ui-kitten/components';
import {TouchableOpacity, View} from 'react-native';
import {styles} from './styles';
import {useState} from 'react';
import ExpandTransfer from '../exrepand-relate';
import {ReceiptRelate} from '../../../../../../../model/interface/receipt.interface';
import TextCM from '../../../../../../components/Text';
import {useTranslation} from 'react-i18next';

const ItemRelateReceipt = ({item}: {item: ReceiptRelate}) => {
  const [isExpand, setIsExpand] = useState(false);
  const {t} = useTranslation();

  const toggleExpand = () => {
    setIsExpand(!isExpand);
  };
  return (
    <>
      <TouchableOpacity style={styles.itemContainer} onPress={toggleExpand}>
        <View style={styles.wrapLabel}>
          <View style={styles.iconContainer}>
            <Icon
              name={isExpand ? 'chevron-down' : 'chevron-right'}
              fill={'#C83A1B'}
              width={12}
              height={12}
            />
          </View>
          <TextCM style={styles.itemLabel}>{t('BLDT.receipt_name')}</TextCM>
        </View>
        <View style={styles.wrapValue}>
          <TextCM
            style={
              styles.itemDetails
            }>{`${item.data.name} - ${item.data.litigantName}`}</TextCM>
        </View>
      </TouchableOpacity>
      {isExpand && <ExpandTransfer item={item} />}
    </>
  );
};

export default ItemRelateReceipt;
