import {create} from 'zustand';
import {MenuViewItem} from '../model/interface/service.interface';

interface ZutandStore {
  listMenuViewBLDT: MenuViewItem[];
  setListMenuViewBLDT: (listMenuView: MenuViewItem[]) => void;
}

const initialSettingState = {
  listMenuViewBLDT: [],
};

export const useZutandStore = create<ZutandStore>((set, get) => ({
  ...initialSettingState,
  setListMenuViewBLDT: (listMenuView: MenuViewItem[]) => {
    set({listMenuViewBLDT: listMenuView});
  },
}));
