import {ActivityIndicator, TouchableOpacity, View} from 'react-native';
import {styles} from './styles';
import Profile from '../../../../../../components/Profile';
import {IconEyeViewDetail} from '../../../../../../../assets/images';
import {useNavigation} from '@react-navigation/native';
import {NavigationName} from '../../../../../../../constants';
import {
  DetailReceiptTransfer,
  ReceiptRelate,
} from '../../../../../../../model/interface/receipt.interface';
import {DateUtils} from '../../../../../../../utils';
import {useEffect, useState} from 'react';
import {useReceiptServices} from '../../../../../../../hooks/apiHooks/useAPI';
import Toast from 'react-native-toast-message';
import {useTranslation} from 'react-i18next';
import {IUserInfo} from '../../../../../../../model/interface/service.interface';
import {useAccountInfoServices} from '../../../../../../../hooks/apiHooks/useAccountInfoServices';
import {listStatusReceipt} from '../../../../../my-receipt/component/modal-filter/helper';
import TextCM from '../../../../../../components/Text';

type Props = {
  item: ReceiptRelate;
};
const ExpandTransfer = ({item}: Props) => {
  const {t} = useTranslation();
  const AccountService = useAccountInfoServices();
  const [detailReceiptTransfer, setDetailReceiptTransfer] =
    useState<DetailReceiptTransfer>();
  const navigation = useNavigation<any>();
  const ReceiptService = useReceiptServices();
  const [createByDetail, setCreateByDetail] = useState<IUserInfo>();
  const getDetailTransferReceiptById = async () => {
    try {
      const res = await ReceiptService.getDetailTransferReceiptById(
        item.data.id,
      );
      if (res) {
        setDetailReceiptTransfer(res);
        const filter = {
          logins: [res.createdBy],
        };
        const resCreateBy = await AccountService.getListAccount(filter);
        setCreateByDetail(resCreateBy?.data[0]);
      } else {
        Toast.show({
          type: 'error',
          text1: t('CM.noti'),
          text2: t('CM.error'),
        });
      }
    } catch (error) {
      console.error(error);
      Toast.show({
        type: 'error',
        text1: t('CM.noti'),
        text2: t('CM.error'),
      });
    }
  };
  useEffect(() => {
    getDetailTransferReceiptById();
  }, []);
  const getStatusElement = (status: string) => {
    const properties = listStatusReceipt.find(
      (item: any) => item.value === status,
    );
    return (
      <View
        style={[
          styles.statusPill,
          {backgroundColor: properties?.bgColor || '#E6F8E6'},
        ]}>
        <TextCM
          style={[styles.statusText, {color: properties?.color || '#39AC6D'}]}>
          {properties?.label ? t('BLDT.draft') : item?.data?.status}
        </TextCM>
      </View>
    );
  };
  const viewDetail = () => {
    navigation.navigate(NavigationName.DetailReceiptScreen, {
      id: detailReceiptTransfer?.id || '',
    });
  };
  return detailReceiptTransfer ? (
    <View style={styles.receiptExpandContainer}>
      <View style={styles.fieldRow}>
        <View style={styles.fieldIconPlaceholder}></View>
        <TextCM style={styles.fieldLabel}>{t('BLDT.request_code')}</TextCM>
        <View style={styles.wrapValue}>
          <TextCM
            style={[
              styles.fieldValue,
              {
                color: '#0066CC',
              },
            ]}>
            {detailReceiptTransfer?.attrs?.caseCode}
          </TextCM>
        </View>
      </View>

      <View style={styles.fieldRow}>
        <View style={styles.fieldIconPlaceholder}></View>
        <TextCM style={styles.fieldLabel}>{t('BLDT.number_THA')}</TextCM>
        <View style={styles.wrapValue}>
          <TextCM style={styles.fieldValue}>
            {detailReceiptTransfer?.attrs?.notificationNumber}
          </TextCM>
        </View>
      </View>

      <View style={styles.fieldRow}>
        <View style={styles.fieldIconPlaceholder}></View>
        <TextCM style={styles.fieldLabel}>{t('BLDT.type_receipt')}</TextCM>
        <View style={styles.wrapValue}>
          <TextCM style={styles.fieldValue}>
            {detailReceiptTransfer?.type}
          </TextCM>
        </View>
      </View>

      <View style={styles.fieldRow}>
        <View style={styles.fieldIconPlaceholder}></View>
        <TextCM style={styles.fieldLabel}>{t('BLDT.money')}</TextCM>
        <View style={styles.wrapValue}>
          <TextCM style={styles.fieldValue}>
            {detailReceiptTransfer?.attrs?.amount}
          </TextCM>
        </View>
      </View>

      <View style={styles.fieldRow}>
        <View style={styles.fieldIconPlaceholder}></View>
        <TextCM style={styles.fieldLabel}>{t('BLDT.payment_method')}</TextCM>
        <View style={styles.wrapValue}>
          <TextCM style={styles.fieldValue}>
            {detailReceiptTransfer?.attrs?.paymentMethod}
          </TextCM>
        </View>
      </View>

      <View style={styles.fieldRow}>
        <View style={styles.fieldIconPlaceholder}></View>
        <TextCM style={styles.fieldLabel}>{t('CM.createdBy')}</TextCM>
        <Profile
          avatar={createByDetail?.imageUrl}
          name={createByDetail?.personalName}
          email={createByDetail?.email || ''}
        />
      </View>

      <View style={styles.fieldRow}>
        <View style={styles.fieldIconPlaceholder}></View>
        <TextCM style={styles.fieldLabel}>{t('CM.createDateCard')}</TextCM>
        <View style={styles.wrapValue}>
          <TextCM style={styles.fieldValue}>
            {DateUtils.convertDateToDDMMYYYY_H_M(
              detailReceiptTransfer?.createdDate,
            )}
          </TextCM>
        </View>
      </View>

      <View style={styles.fieldRow}>
        <View style={styles.fieldIconPlaceholder}></View>
        <TextCM style={styles.fieldLabel}>{t('CM.status')}</TextCM>
        {detailReceiptTransfer?.status &&
          getStatusElement(detailReceiptTransfer?.status || '')}
      </View>

      <View style={styles.fieldRow}>
        <View style={styles.fieldIconPlaceholder}></View>
        <TextCM style={styles.fieldLabel}>{t('CM.acion')}</TextCM>
        <TouchableOpacity style={styles.actionButton} onPress={viewDetail}>
          <IconEyeViewDetail width={14} height={10} />
        </TouchableOpacity>
      </View>
    </View>
  ) : (
    <View
      style={[
        styles.receiptExpandContainer,
        {flex: 1, justifyContent: 'center', alignItems: 'center', height: 200},
      ]}>
      <ActivityIndicator size="large" color="#0000ff" />
    </View>
  );
};
export default ExpandTransfer;
