import React, {useCallback, useEffect, useState} from 'react';
import HeaderCM from '../../components/Header/HeaderCM';
import {
  ActivityIndicator,
  FlatList,
  Keyboard,
  TouchableOpacity,
  TouchableWithoutFeedback,
  View,
} from 'react-native';
import {useTranslation} from 'react-i18next';

// import RenderTabView from './component/tab-view';
import {Icon, Input} from '@ui-kitten/components';
import BottomSheetCM from '../../components/BottomSheet';
import ModalFilter from './component/modal-filter';
import {styles} from './styles';
import {Color, Font} from '../../../constants';
import {
  useReceiptZustandStore,
  ValueFilterSearch,
} from './store/myReceiptZustandStore';
import {useReceiptServices} from '../../../hooks/apiHooks/useAPI';
import {
  listPayment,
  listRequestStatus,
  listStatusReceipt,
} from './component/modal-filter/helper';
import useDebounce from '../../../hooks/useDebounce';
import {IReceiptItem} from '../../../model/interface/receipt.interface';
import TextCM from '../../components/Text';
import {useFocusEffect, useRoute} from '@react-navigation/native';
import ReceiptItem from './component/receipt-item';
import LoadingMore from '../../components/LoadingMore';
import {DateUtils} from '../../../utils';

const MyReceiptScreen = () => {
  const {t} = useTranslation();
  const route = useRoute<any>();
  const isReload = route?.params?.isReload || false;
  const [value, setValue] = useState('');
  const valueTextSearch = useDebounce(value, 300);
  const [visibleFilter, setVisibleFilter] = useState(false);
  const {setListTypeReceipt, listTypeReceipt} = useReceiptZustandStore();

  const [valueFilterSearch, setValueFilterSearch] =
    useState<ValueFilterSearch>();
  const [listReceipt, setListReceipt] = useState<IReceiptItem[]>([]);
  const [isRefreshing, setIsFreshing] = useState(false);
  const [isLoadMore, setIsLoadMore] = useState(false);
  const [isLoading, setIsLoading] = useState(false);
  const [page, setPage] = useState(0);
  const [totalPages, setTotalPages] = useState(0);
  const [typereceipt] = useState([
    {type: 'default', name: t('BLDT.default_type_receipt')},
    {type: 'transfer_voucher', name: t('BLDT.transfer_voucher_type_receipt')},
  ]);
  const [currentTypeReceipt, setCurrentTypeReceipt] = useState<
    'default' | 'transfer_voucher'
  >('default');
  const ReceiptService = useReceiptServices();

  useEffect(() => {
    getListTypeReceipt();
  }, []);

  useFocusEffect(
    useCallback(() => {
      getDataReceipt(0, false);
    }, [isReload, valueFilterSearch, valueTextSearch, currentTypeReceipt]),
  );

  const getListTypeReceipt = async () => {
    try {
      const data = await ReceiptService.getReceiptTemplate();
      if (data) {
        setListTypeReceipt(
          data.map((d: any) => ({
            id: d.id,
            label: d.name,
            value: d.code,
          })),
        );
      }
    } catch (error) {}
  };
  const getDataReceipt = async (page: number, isLoadMore?: boolean) => {
    try {
      if (isLoadMore) {
        setIsLoadMore(true);
      } else {
        setIsLoading(true);
      }
      const bodySearch: any = {
        q: valueTextSearch?.trim(),
        terms: {
          transferType: currentTypeReceipt,
        },
      };
      if (valueFilterSearch?.paymentMethod) {
        bodySearch.terms.paymentMethod = valueFilterSearch?.paymentMethod?.map(
          item => listPayment[item.row].label,
        );
      }
      if (valueFilterSearch?.status) {
        bodySearch.terms.status = valueFilterSearch?.status?.map(
          item => listStatusReceipt[item.row].value,
        );
      }
      if (valueFilterSearch?.type) {
        bodySearch.terms.type = valueFilterSearch?.type?.map(
          item => listTypeReceipt[item.row].value,
        );
      }
      if (valueFilterSearch?.requestStatus) {
        bodySearch.terms.requestStatus = valueFilterSearch?.requestStatus?.map(
          item => listRequestStatus[item.row].value,
        );
      }
      if (valueFilterSearch?.rangeDay?.startDate) {
        if (bodySearch?.multiRange?.[0]) {
          bodySearch.multiRange[0] = {
            ...bodySearch?.multiRange?.[0],
            gte: DateUtils.formatToIsoDate(
              valueFilterSearch?.rangeDay?.startDate.toISOString(),
              'start',
            ),
          };
        } else {
          bodySearch.multiRange = [];
          bodySearch.multiRange[0] = {
            field: 'createdDate',
            gte: DateUtils.formatToIsoDate(
              valueFilterSearch?.rangeDay?.startDate.toISOString(),
              'start',
            ),
            lte: null,
          };
        }
      }
      if (valueFilterSearch?.rangeDay?.endDate) {
        if (bodySearch?.multiRange?.[0]) {
          bodySearch.multiRange[0] = {
            ...bodySearch?.multiRange?.[0],
            lte: DateUtils.formatToIsoDate(
              valueFilterSearch?.rangeDay?.endDate.toISOString(),
              'end',
            ),
          };
        } else {
          bodySearch.multiRange = [];
          bodySearch.multiRange[0] = {
            field: 'createdDate',
            gte: null,
            lte: DateUtils.formatToIsoDate(
              valueFilterSearch?.rangeDay?.endDate.toISOString(),
              'end',
            ),
          };
        }
      }
      const res = await ReceiptService.getReceipt(page, 20, bodySearch);
      if (page === 0) {
        setListReceipt(res?.data);
        setTotalPages(res?.totalData);
      } else {
        setListReceipt([...listReceipt, ...res?.data]);
      }
    } catch (error) {
    } finally {
      setIsLoading(false);
      setIsLoadMore(false);
      setIsFreshing(false);
    }
  };

  const handleSubmitFilter = () => {
    setVisibleFilter(false);
  };

  const checkIsFilter = () => {
    return (
      valueFilterSearch?.rangeDay?.endDate ||
      valueFilterSearch?.rangeDay?.startDate ||
      valueFilterSearch?.paymentMethod?.length ||
      valueFilterSearch?.status?.length ||
      valueFilterSearch?.type?.length
    );
  };

  const handleChangeTypeReceipt = (type: 'default' | 'transfer_voucher') => {
    setCurrentTypeReceipt(type);
  };

  const renderTypeReceipt = (item: any) => {
    return (
      <TouchableOpacity
        key={item.type}
        onPress={() => handleChangeTypeReceipt(item.type)}
        style={styles.containerTypereceipt}>
        {currentTypeReceipt === item.type ? (
          <View style={styles.typeReceiptSelected}>
            <View
              style={{
                width: 8,
                height: 8,
                backgroundColor: Color.White,
                borderRadius: 10,
              }}></View>
          </View>
        ) : (
          <View style={styles.typeReceiptDefault}></View>
        )}
        <TextCM
          style={[
            styles.textTypeReceipt,
            {
              color: currentTypeReceipt === item.type ? '#262D34' : '#667085',
            },
          ]}>
          {item.name}
        </TextCM>
      </TouchableOpacity>
    );
  };

  const onRefresh = () => {
    setIsFreshing(true);
    setPage(0);
    getDataReceipt(0, false);
  };

  const handleLoadMore = () => {
    if (page < Math.ceil(totalPages / 20)) {
      getDataReceipt(page + 1, true);
      setPage(page + 1);
    }
  };

  const getNumberFilter = () => {
    let count = 0;
    if (valueFilterSearch?.paymentMethod?.length) {
      count += 1;
    }
    if (valueFilterSearch?.status?.length) {
      count += 1;
    }
    if (valueFilterSearch?.type?.length) {
      count += 1;
    }
    if (valueFilterSearch?.requestStatus?.length) {
      count += 1;
    }
    if (
      valueFilterSearch?.rangeDay?.startDate ||
      valueFilterSearch?.rangeDay?.endDate
    ) {
      count += 1;
    }
    return count;
  };

  return (
    <TouchableWithoutFeedback onPress={() => Keyboard.dismiss()}>
      <View style={styles.ctn}>
        <HeaderCM
          title={t('BLDT.my_receipt')}
          useLinearGradient={false}
          style={{backgroundColor: Color.BgPrimary}}
          contentStyle={{backgroundColor: Color.BgPrimary}}
        />
        <View style={styles.wrapInputSearch}>
          <Input
            allowFontScaling={false}
            style={styles.inputSearch}
            textStyle={{color: Color.Black}}
            placeholderTextColor={'#9FB0C7'}
            placeholder={t('CM.search')}
            value={value}
            status="basic"
            onChangeText={setValue}
            accessoryLeft={
              <TouchableOpacity onPress={() => false}>
                <Icon fill={'#9FB0C7'} name="search" />
              </TouchableOpacity>
            }
            accessoryRight={
              value ? (
                <TouchableOpacity onPress={() => setValue('')}>
                  <Icon name="close-outline" fill={Color.Black} />
                </TouchableOpacity>
              ) : undefined
            }
          />
          <TouchableOpacity
            onPress={() => setVisibleFilter(true)}
            style={styles.wrapFilterIcon}>
            <Icon
              fill={Color.White}
              name={checkIsFilter() ? 'funnel' : 'funnel-outline'}
              width={25}
              height={25}
            />
            <View style={styles.ctnFilter}>
              <TextCM style={styles.numbFilter}>{getNumberFilter()}</TextCM>
            </View>
          </TouchableOpacity>
        </View>

        <View style={{flexDirection: 'row', gap: 16, marginBottom: 10}}>
          {typereceipt.map((item: any) => renderTypeReceipt(item))}
        </View>

        {isLoading && (
          <ActivityIndicator
            style={{marginTop: 10}}
            color={Color.BgPrimary}
            size="large"
          />
        )}

        {!isLoading && (
          <FlatList
            showsVerticalScrollIndicator={false}
            data={listReceipt}
            keyExtractor={item => item?.data?.id}
            renderItem={({item}) => <ReceiptItem receipt={item} />}
            onEndReachedThreshold={0.5}
            onRefresh={onRefresh}
            refreshing={isRefreshing}
            onEndReached={handleLoadMore}
            ListEmptyComponent={() => (
              <View
                style={{
                  alignItems: 'center',
                  justifyContent: 'center',
                  flex: 1,
                }}>
                <TextCM>{t('CM.emptyData')}</TextCM>
              </View>
            )}
            contentContainerStyle={{rowGap: 16}}
            ListFooterComponent={() => isLoadMore && <LoadingMore />}
          />
        )}

        <BottomSheetCM
          title={t('CM.filter')}
          onClose={() => setVisibleFilter(false)}
          isVisible={visibleFilter}
          renderContent={
            <ModalFilter
              handleSubmitFilter={handleSubmitFilter}
              onClose={() => setVisibleFilter(false)}
              setValueFilterSearch={setValueFilterSearch}
              valueFilterSearch={valueFilterSearch}
            />
          }
        />
      </View>
    </TouchableWithoutFeedback>
  );
};

export default MyReceiptScreen;
