import {getConfig} from './httpClient';
export const createReceiptServices = (fetchRequest: any) => ({
  async getReceipt(page: number, size: number, body?: any) {
    const endPoint = `/services/thads-bldt/api/search/electronic-receipts?page=${page}&size=${size}&sort=createdDate,desc&type=owner`;
    try {
      const data = await fetchRequest({
        url: getConfig().BASE_URL + endPoint,
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(body) || '{}',
      });
      const totalData = data?.headers.get('x-total-count') || 0;
      return Promise.resolve({
        data: data?.data,
        totalData: totalData,
      });
    } catch (error) {
      Promise.reject(error);
    }
  },
  async getReceiptById(id: string) {
    //getReceiptById
    const endPoint = `/services/thads-bldt/api/electronic-receipts/${id}`;
    try {
      const data = await fetchRequest({
        url: getConfig().BASE_URL + endPoint,
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
        },
      });
      return Promise.resolve(data.data);
    } catch (error) {
      Promise.reject(error);
    }
  },
  async getListTranferReceiptByParentId(params?: any, body?: any) {
    const endPoint = `/services/thads-bldt/api/search/electronic-receipts?page=${params.page}&size=${params.size}&sort=createdDate,desc`;
    try {
      const data = await fetchRequest({
        url: getConfig().BASE_URL + endPoint,
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(body),
      });
      const totalData = data?.headers.get('x-total-count') || 0;
      return Promise.resolve({
        data: data?.data,
        totalData: totalData,
      });
    } catch (error) {
      Promise.reject(error);
    }
  },
  async deleteReceiptById(id: string) {
    try {
      const endPoint = `/services/thads-bldt/api/electronic-receipts/${id}`;
      const data = await fetchRequest({
        url: getConfig().BASE_URL + endPoint,
        method: 'DELETE',
        headers: {
          'Content-Type': 'application/json',
        },
        typeOfResponse: '',
      });
      return Promise.resolve(data.data);
    } catch (error) {
      Promise.reject(error);
    }
  },
  async getDetailTransferReceiptById(parentId: any) {
    const endPoint = `/services/thads-bldt/api/electronic-receipts/${parentId}`;
    try {
      const data = await fetchRequest({
        url: getConfig().BASE_URL + endPoint,
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
        },
      });
      return Promise.resolve(data.data);
    } catch (error) {
      Promise.reject(error);
    }
  },

  async getListRelativeFile(params: any) {
    try {
      const endPoint = `/services/erequest/api/attachments/get-by-ticketId`;
      const data = await fetchRequest({
        url: getConfig().BASE_URL + endPoint,
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
        },
        params: params,
      });
      const totalData = data?.headers.get('x-total-count') ?? 0;
      const listData = data?.data;
      return Promise.resolve({
        data: listData,
        totalRecords: Number(totalData),
      });
    } catch (error) {
      Promise.reject(error);
    }
  },

  async deleteRelateFileById(id: string, accessToken: string) {
    try {
      const endPoint = `/services/erequest/api/attachments/${id}`;
      const data = await fetchRequest({
        url: getConfig().BASE_URL + endPoint,
        method: 'DELETE',
        headers: {
          'Content-Type': 'application/json',
          Authorization: 'Bearer' + accessToken,
        },
        typeOfResponse: '',
      });
      return Promise.resolve(data.data);
    } catch (error) {
      Promise.reject(error);
    }
  },
  async uploadFileRelative(body: FormData, accessToken: string) {
    try {
      const endPoint = `/services/erequest/api/attachments`;
      const data = await fetchRequest({
        url: getConfig().BASE_URL_EREQUEST + endPoint,
        method: 'POST',
        headers: {
          'Content-Type': 'multipart/form-data',
          Authorization: 'Bearer' + accessToken,
        },
        body: body,
      });
      return Promise.resolve(data?.data);
    } catch (error) {
      Promise.reject(error);
    }
  },

  async getHistoryReceiptById(id: string) {
    try {
      const endPoint = `/services/thads-bldt/api/receipt-histories/find-by-resource/${id}`;
      const data = await fetchRequest({
        url: getConfig().BASE_URL + endPoint,
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
        },
      });
      return Promise.resolve(data?.data);
    } catch (error) {
      Promise.reject(error);
    }
  },
  async getReleaseReceipt(id: string) {
    try {
      const endPoint = `/services/thads-bldt/api/object-storage-configs/all/${id}`;
      const data = await fetchRequest({
        url: getConfig().BASE_URL + endPoint,
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
        },
      });
      return Promise.resolve(data?.data);
    } catch (error) {
      Promise.reject(error);
    }
  },

  async viewFile(body: FormData, accessToken?: string) {
    try {
      const endPoint = `/services/s3service/api/view`;
      const data = await fetchRequest({
        url: getConfig().BASE_URL + endPoint,
        method: 'POST',
        headers: {
          'Content-Type': 'multipart/form-data',
          Authorization: 'Bearer ' + accessToken,
        },
        body: body,
      });
      return Promise.resolve(data?.data);
    } catch (error) {
      Promise.reject(error);
    }
  },

  async reGenerateNumberReceipt(id: string) {
    try {
      const endPoint =
        '/services/thads-bldt/api/electronic-receipts/regenerate/' + id;
      const data = await fetchRequest({
        url: getConfig().BASE_URL + endPoint,
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
        },
        typeOfResponse: 'text',
      });
      return Promise.resolve(data?.data);
    } catch (error) {}
  },

  async getReceiptTemplate() {
    try {
      const endPoint = `/services/thads-bldt/api/receipt-templates/all`;
      const data = await fetchRequest({
        url: getConfig().BASE_URL + endPoint,
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
        },
      });
      return Promise.resolve(data?.data);
    } catch (error) {}
  },

  async getReceiptStatus() {
    try {
      const endPoint =
        '/services/ecategory/api/data/code/RECEIPT_STATUS?page=0&size=100';
      const data = await fetchRequest({
        url: getConfig().BASE_URL + endPoint,
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
        },
      });
      return Promise.resolve(data?.data);
    } catch (error) {}
  },

  async getDashboardReport() {
    try {
      const endpoint =
        '/services/thads-bldt/api/search/electronic-receipts/report';
      const data = await fetchRequest({
        url: getConfig().BASE_URL + endpoint,
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          groupByField: 'status',
        }),
      });
      return Promise.resolve(data?.data);
    } catch (error) {}
  },
});
