//import liraries
import React, {useEffect, useState} from 'react';
import {FlatList, ScrollView, useWindowDimensions, View} from 'react-native';
import styles from './styles';
import {useTranslation} from 'react-i18next';
import {isNull} from 'lodash';
import {Icon} from '@ui-kitten/components';
import TextCM from '../../../../components/Text';
import DateUtils from '../../../../../utils/DateUtils';
import {useReceiptServices} from '../../../../../hooks/apiHooks/useAPI';
import {IHistoryReceiptItem} from '../../../../../model/interface/receipt.interface';
import {TYPE_REQUEST_HISTORY} from '../../../../../model/type/status';

type Props = {
  onClose: () => void;
  id: string;
};

// create a component
const HistoryTicket = ({onClose, id}: Props) => {
  const {t} = useTranslation();
  const {height} = useWindowDimensions();
  const ReceiptService = useReceiptServices();
  const [listHistories, setListHistories] = useState<IHistoryReceiptItem[]>([]);
  useEffect(() => {
    getTicketHistories();
  }, []);

  const getTicketHistories = async () => {
    try {
      const dataHistory = await ReceiptService.getHistoryReceiptById(id);
      if (dataHistory) {
        setListHistories(dataHistory);
      } else {
        setListHistories([]);
      }
    } catch (error) {
      console.error(error);
    }
  };

  const renderIcon = (bgColor: string, iconName: string, fill: string) => {
    return (
      <View
        style={[
          {
            backgroundColor: bgColor,
          },
          styles.ctnViewIcon,
        ]}>
        <Icon fill={fill} name={iconName} width={15} height={15} />
      </View>
    );
  };

  const getValueIcon = (action: TYPE_REQUEST_HISTORY) => {
    switch (action) {
      case 'signing_cash':
        return renderIcon('#E6F8FF', 'flip-2-outline', '#01BCFE');
      case 'signed_cash':
        return renderIcon('#E8F7EF', 'done-all-outline', '#39AC6D');
      case 'signing_recording_vouchers':
        return renderIcon('#feeef6', 'person-add', '#dc569b');
      case 'signed_recording_vouchers':
        return renderIcon('#E8F7EF', 'done-all-outline', '#39AC6D');
      case 'signing_transfer_voucher':
        return renderIcon('#FCEEED', 'edit-2', '#E14337');
      case 'signed_transfer_voucher':
        return renderIcon('#E8F7EF', 'done-all-outline', '#39AC6D');
      case 'processing_receipt':
        return renderIcon('#EF5DA81A', 'done-all-outline', '#EF5DA8');
      case 'released_receipt':
        return renderIcon('#E8F7EF', 'done-all-outline', '#39AC6D');
      case 'cancelled_receipt':
        return renderIcon('#fdeded', 'close-circle', '#e14437');
      case 'created_receipt':
        return renderIcon('#edf2fd', 'plus-circle-outline', '#97b2f0');
      case 'draft_receipt':
        return renderIcon('#F2F5F8', 'save-outline', '#00204DE5');
      case 'document_confirm':
      case 'completed':
        return renderIcon('#E8F7EF', 'done-all-outline', '#39AC6D');
      default:
        return renderIcon('#FCEEED', 'edit-2', '#E14337');
    }
  };

  const renderItem = ({
    item,
    index,
  }: {
    item: IHistoryReceiptItem;
    index: number;
  }) => {
    return (
      <>
        {!isNull('item.createdBy') && (
          <>
            <View style={styles.ctnItem}>
              {getValueIcon(item.status)}
              <View style={{rowGap: 4, flex: 1}}>
                <View>
                  <TextCM style={styles.title}>
                    {t(`BLDT.history.${item.status}`)}
                  </TextCM>
                </View>
                <View style={styles.ctnDes}>
                  <TextCM style={styles.Des}>
                    {`${DateUtils.convertDateToDDMMYYYY_H_M(
                      item.createdDate,
                    )} ${t('TK.by')} ${item.createdBy}`}
                  </TextCM>
                </View>
              </View>
            </View>
            {listHistories.length - 1 !== index && (
              <View style={styles.tabHoz}></View>
            )}
          </>
        )}
      </>
    );
  };

  return (
    <>
      <ScrollView
        showsHorizontalScrollIndicator={false}
        showsVerticalScrollIndicator={false}
        style={{maxHeight: (height / 3) * 2}}>
        <FlatList
          scrollEnabled={false}
          keyExtractor={item => item.id}
          data={listHistories?.reverse()}
          renderItem={renderItem}
          showsHorizontalScrollIndicator={false}
          showsVerticalScrollIndicator={false}
          ListEmptyComponent={() => (
            <View
              style={{
                alignItems: 'center',
                justifyContent: 'center',
                flex: 1,
              }}>
              <TextCM>{t('CM.emptyData')}</TextCM>
            </View>
          )}
        />
      </ScrollView>
    </>
  );
};

//make this component available to the app
export default HistoryTicket;
